B.bAe=new A.r("1. Informa\xe7\xf5es que Coletamos",null,B.cl,null,null,null,null,null,null,null,null)
B.bzY=new A.r("O Ache Obra pode coletar informa\xe7\xf5es fornecidas diretamente pelo usu\xe1rio durante o cadastro, utiliza\xe7\xe3o e atualiza\xe7\xe3o do perfil, incluindo nome, e-mail, telefone/WhatsApp, CPF quando necess\xe1rio, cidade, estado, categoria e perfil de uso, como Cliente, Profissional, Arquiteto ou Engenheiro.",null,B.cN,null,null,null,null,null,null,null,null)
B.af=new A.bs(null,10,null,null)
B.buv=new A.r("Tamb\xe9m poder\xe3o ser armazenadas informa\xe7\xf5es inseridas voluntariamente pelo usu\xe1rio em seu perfil ou durante a utiliza\xe7\xe3o dos recursos disponibilizados pelo aplicativo, incluindo informa\xe7\xf5es profissionais, descri\xe7\xf5es, solicita\xe7\xf5es, publica\xe7\xf5es, imagens e outros conte\xfados necess\xe1rios ao funcionamento da plataforma.",null,B.cN,null,null,null,null,null,null,null,null)
B.bwt=new A.r("Podemos ainda coletar informa\xe7\xf5es t\xe9cnicas necess\xe1rias ao funcionamento e \xe0 seguran\xe7a do servi\xe7o, como identificadores da conta, informa\xe7\xf5es de autentica\xe7\xe3o, identificadores do dispositivo, tokens utilizados para notifica\xe7\xf5es e registros t\xe9cnicos relacionados ao funcionamento do aplicativo.",null,B.cN,null,null,null,null,null,null,null,null)
B.bsM=new A.r("2. Uso das Informa\xe7\xf5es",null,B.cl,null,null,null,null,null,null,null,null)
B.btG=new A.r("As informa\xe7\xf5es coletadas s\xe3o utilizadas para permitir o funcionamento do Ache Obra, criar e administrar contas de usu\xe1rios, disponibilizar perfis, conectar clientes a profissionais e prestadores de servi\xe7os da constru\xe7\xe3o civil, permitir a utiliza\xe7\xe3o dos recursos da plataforma e facilitar a comunica\xe7\xe3o entre os usu\xe1rios.",null,B.cN,null,null,null,null,null,null,null,null)
B.byq=new A.r("Os dados tamb\xe9m podem ser utilizados para autentica\xe7\xe3o, seguran\xe7a da conta, preven\xe7\xe3o de uso indevido, gerenciamento de planos e recursos contratados, atendimento ao usu\xe1rio, envio de notifica\xe7\xf5es relacionadas ao funcionamento do aplicativo e melhoria dos servi\xe7os oferecidos.",null,B.cN,null,null,null,null,null,null,null,null)
B.byG=new A.r("3. Servi\xe7os de Terceiros",null,B.cl,null,null,null,null,null,null,null,null)
B.byM=new A.r("Para fornecer determinadas funcionalidades, o Ache Obra utiliza servi\xe7os tecnol\xf3gicos de terceiros. Entre eles est\xe3o o Supabase, utilizado para autentica\xe7\xe3o, banco de dados e armazenamento de informa\xe7\xf5es, e servi\xe7os do Firebase, do Google, utilizados para funcionalidades como o envio de notifica\xe7\xf5es.",null,B.cN,null,null,null,null,null,null,null,null)
B.bvh=new A.r("Esses prestadores podem processar informa\xe7\xf5es estritamente necess\xe1rias para a execu\xe7\xe3o dos respectivos servi\xe7os, de acordo com suas pr\xf3prias pol\xedticas de privacidade e pr\xe1ticas de seguran\xe7a.",null,B.cN,null,null,null,null,null,null,null,null)
B.bvD=new A.r("O Ache Obra n\xe3o vende nem aluga os dados pessoais dos usu\xe1rios para terceiros e n\xe3o compartilha dados pessoais para fins de publicidade ou marketing de terceiros.",null,B.cN,null,null,null,null,null,null,null,null)
B.bvw=new A.r("4. Pagamentos e Planos",null,B.cl,null,null,null,null,null,null,null,null)
B.bz3=new A.r("O Ache Obra pode oferecer planos pagos, assinaturas e outros recursos opcionais. Quando uma compra \xe9 realizada por meio de uma loja de aplicativos ou de um provedor de pagamento autorizado, determinadas informa\xe7\xf5es da transa\xe7\xe3o s\xe3o processadas pelo respectivo provedor.",null,B.cN,null,null,null,null,null,null,null,null)
B.bye=new A.r("O Ache Obra poder\xe1 receber e armazenar informa\xe7\xf5es necess\xe1rias para identificar e validar a compra, como produto ou plano adquirido, identificadores da transa\xe7\xe3o, situa\xe7\xe3o do pagamento e per\xedodo de validade, quando aplic\xe1vel.",null,B.cN,null,null,null,null,null,null,null,null)
B.bu4=new A.r("5. Seguran\xe7a das Informa\xe7\xf5es",null,B.cl,null,null,null,null,null,null,null,null)
B.bA0=new A.r("Adotamos medidas t\xe9cnicas e administrativas destinadas a proteger as informa\xe7\xf5es pessoais contra acessos n\xe3o autorizados, perda, altera\xe7\xe3o, divulga\xe7\xe3o ou uso indevido.",null,B.cN,null,null,null,null,null,null,null,null)
B.bAj=new A.r("Embora sejam adotadas medidas de seguran\xe7a compat\xedveis com os servi\xe7os oferecidos, nenhum sistema eletr\xf4nico de armazenamento ou transmiss\xe3o de informa\xe7\xf5es pode garantir seguran\xe7a absoluta.",null,B.cN,null,null,null,null,null,null,null,null)
B.buW=new A.r("6. Reten\xe7\xe3o dos Dados",null,B.cl,null,null,null,null,null,null,null,null)
B.byR=new A.r("Os dados pessoais s\xe3o mantidos pelo per\xedodo necess\xe1rio para disponibilizar os servi\xe7os do Ache Obra, manter a conta do usu\xe1rio e cumprir as finalidades descritas nesta Pol\xedtica de Privacidade.",null,B.cN,null,null,null,null,null,null,null,null)
B.bsF=new A.r("Ap\xf3s uma solicita\xe7\xe3o de exclus\xe3o, os dados vinculados \xe0 conta ser\xe3o exclu\xeddos ou anonimizados, ressalvadas as informa\xe7\xf5es cuja conserva\xe7\xe3o seja necess\xe1ria para cumprimento de obriga\xe7\xf5es legais ou regulat\xf3rias, preven\xe7\xe3o de fraudes, seguran\xe7a, resolu\xe7\xe3o de disputas ou exerc\xedcio regular de direitos.",null,B.cN,null,null,null,null,null,null,null,null)
B.bu7=new A.r("7. Exclus\xe3o de Conta e Direitos do Usu\xe1rio (LGPD)",null,B.cl,null,null,null,null,null,null,null,null)
